import{neuralComposer,neuralFields}from'./music-neural.js';
import{applySongMotif}from'./music-song-motif.js';
import{arrangeSections}from'./music-arrange.js';
import{composeSong,songStructureFields,readSongStructure}from'./music-song.js';
import{musicScore,referenceStyle}from'./music-motifs.js';
import{compileMusic,checkScore,MUSIC_MOODS,MUSIC_GENRES,MUSIC_KEYS,MUSIC_SCALES}from'./music-compose.js';
import{musicStyle}from'./music-styles.js';
import{learnPhrases,blendPhraseModels}from'./music-learning.js';
import{MOTIF_USAGE,MOTIF_SCOPES}from'./music-song-motif.js';
import{mountMotifRange}from'./music-range-ui.js';
import{applyShatteredTreatment}from'./music-shattered-treatment.js';

export function referenceComposer(api,initial,initialScore,initialRange){
 const neural=api.neural||neuralComposer();let serial=0,busy=false;
 const cancel=()=>{serial++;neural.cancel();api.stop();};const $=s=>document.querySelector(s),esc=api.esc,library=api.tracks(),sources=library.some(t=>t.id===initial.id)?library:[initial,...library];
 let primary=initial,reference=initialScore,range={...initialRange},score,rangeView,extraScore=null;
 const opts=(rows,value)=>rows.map(([id,name])=>`<option value="${esc(String(id))}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join(''),style=referenceStyle(reference,range.track);
 api.modal('Compose from a reference',`<label>Name<input id="referenceName" maxlength="120" value="${esc(initial.name+' new theme')}"></label><div class="studio-grid"><label>Source song<select id="referenceSource">${opts(sources.map(t=>[t.id,t.name]),initial.id)}</select></label><label>Melody part<select id="referencePart"></select></label></div><details open><summary>Select the motif · A to B</summary><div id="referenceRangeView"></div><div class="studio-grid"><label>A · first bar<input id="referenceStartBar" type="number" min="1" step="any"></label><label>B · ends after bar<input id="referenceEndBar" type="number" min="0.0625" step="any"></label></div><p id="referenceSelection" class="studio-status"></p><button id="referenceHearRiff" type="button">▶ Loop selected motif</button></details><fieldset><legend>How to use this motif</legend><div class="studio-grid"><label>Treatment<select id="referenceMode"><option value="inspired">Inspired · develop a related phrase</option><option value="motif">Exact motif · preserve selected notes</option></select></label><label>Placement<select id="referenceUsage">${opts(Object.entries(MOTIF_USAGE),'sparse')}</select></label><label>Sections<select id="referenceScope">${opts(Object.entries(MOTIF_SCOPES),'loop')}</select></label></div><label>Motif resemblance <output id="referenceInfluenceValue">50</output>%<input id="referenceInfluence" type="range" min="0" max="100" value="50"></label><p>0 leaves the motif out. Higher resemblance retains more of its contour and rhythm. Exact mode preserves the selected pitches and timing at each scheduled appearance.</p><label><input id="referencePitch" type="checkbox" checked> Preserve exact pitches in Exact mode</label><label><input id="referenceRhythm" type="checkbox" checked> Preserve exact rhythm in Exact mode</label></fieldset><details open><summary>Scene style and genre</summary><div class="studio-grid"><label>Scene style<select id="referenceMood">${opts(Object.keys(MUSIC_MOODS).map(v=>[v,v]),'Battle')}</select></label><label>Genre<select id="referenceGenre">${opts(Object.keys(MUSIC_GENRES).map(v=>[v,v]),'Game soundtrack')}</select></label><label>Key<select id="referenceKey">${opts(MUSIC_KEYS.map((v,i)=>[i,v]),style.key)}</select></label><label>Scale<select id="referenceScale">${opts(Object.keys(MUSIC_SCALES).map(v=>[v,v]),style.scale)}</select></label><label>Tempo<input id="referenceTempo" type="number" min="10" max="510" step="2" value="${style.tempo}"></label><label>Variation seed<input id="referenceSeed" type="number" min="0" max="4294967295" value="1"></label><label>Complexity<input id="referenceComplexity" type="range" min="0" max="100" value="45"></label><label>Experimentation<input id="referenceAdventure" type="range" min="0" max="100" value="15"></label><label>Atmosphere treatment<select id="referenceTreatment"><option value="none">Original source identity</option><option value="worn-subtle">Worn · preserve identity</option><option value="worn-route">Worn route · familiar but damaged</option><option value="worn-strong">Worn · damaged memory</option></select></div><p id="referenceStyleDescription" class="callout"></p><p id="referenceTreatmentHint" class="hint-line">Choose Worn route to keep a route’s signature melody while making its harmony cold, sparse and uneasy.</p></details><details><summary>Learn phrasing from full songs</summary><label><input id="referenceLearn" type="checkbox" checked> Analyse the entire selected melody part</label><label>Phrase influence <output id="referenceLearningValue">55</output>%<input id="referenceLearning" type="range" min="0" max="100" value="55"></label><p>The full part contributes rhythm phrases, register and interval transitions. Only A–B is reused as a motif. Analysis runs locally on your device; this is a symbolic phrase model, not a pretrained composer.</p><label>Additional reference<select id="referenceExtra"></select></label><label id="referenceExtraPartLabel" hidden>Additional melody part<select id="referenceExtraPart"></select></label><p id="referenceLearningReport"></p></details>${neuralFields('reference')}${songStructureFields('reference')}<div class="studio-actions"><button id="referencePreview" type="button">▶ Preview new track</button><button id="referenceOriginal" type="button" ${initial.asset?'':'disabled'}>▶ Source song</button><button id="referenceNext" type="button">Next variation</button><button id="referenceStop" type="button">■ Stop preview</button></div><p id="referenceReport" class="studio-status"></p><p class="hint-line">Placement applies to the finished arrangement. Intro plays once; verse and bridge loop. Exact motifs can contain notes outside the chosen scale. Instrument banks can be changed in the arranger.</p>`,async()=>{if(busy)return false;busy=true;const job=++serial;try{await build();if(job!==serial)return false;api.arrange({score,name:$('#referenceName').value.trim()||'New theme',warnings:[]});}catch(e){if(e.name==='AbortError')return false;throw e;}finally{busy=false;}},'Arrange generated track');
 const safe=fn=>async()=>{if(busy)return;busy=true;const job=++serial;try{await fn(job);}catch(e){if(e.name!=='AbortError')api.error(e);}finally{busy=false;}},parts=s=>s.tracks.map((p,i)=>[i,(p.name||'Part '+(i+1))+' · '+p.notes.length+' notes']).filter(([i])=>s.tracks[i].notes.length);
 function selection(){$('#referenceSelection').textContent=primary.name+' → '+(reference.tracks[range.track].name||'Part '+(range.track+1))+` · ${range.end-range.start} ticks selected`;$('#referenceStartBar').value=1+range.start/96;$('#referenceEndBar').value=range.end/96;}
 const body=document.querySelector('#dialogBody');body?.addEventListener('input',cancel);
 function readRange(){range.start=Math.round((+$('#referenceStartBar').value-1)*96);range.end=Math.round(+$('#referenceEndBar').value*96);if(range.start<0||range.end>reference.length||range.end<=range.start)throw Error('Select A before B, inside the source song.');}
 function drawRange(){selection();rangeView=mountMotifRange({root:$('#referenceRangeView'),score:reference,part:range.track,range,onRange:r=>{cancel();range={...range,...r};selection();},error:api.error});}
 function drawParts(){const rows=parts(reference);if(!reference.tracks[range.track]?.notes.length)range.track=rows[0][0];$('#referencePart').innerHTML=opts(rows,range.track);drawRange();}
 function loadExtra(){const t=library.find(t=>t.id===$('#referenceExtra').value);extraScore=t?musicScore(t.asset).score:null;$('#referenceExtraPartLabel').hidden=!extraScore;$('#referenceExtraPart').innerHTML=extraScore?opts(parts(extraScore),parts(extraScore)[0]?.[0]):'';}
 function drawExtra(){$('#referenceExtra').innerHTML=opts([['','None · selected part only'],...library.filter(t=>t.id!==primary.id).map(t=>[t.id,t.name])],'');loadExtra();}
 function describe(){const p=musicStyle($('#referenceMood').value,$('#referenceGenre').value),t=$('#referenceTreatment').value;$('#referenceStyleDescription').textContent=p.description;$('#referenceTreatmentHint').textContent=t==='none'?'The source arrangement stays intact.':t==='worn-strong'?'Strong worn treatment: slowed, sparse, minor-coloured and deliberately damaged while the selected lead remains recognizable.':t==='worn-route'?'Route treatment: preserve the route’s contour, then add cold space, lonely bass and broken echoes.':'Subtle worn treatment: a darker arrangement with the source identity intact.';}
 async function build(){const revision=serial;api.stop();readRange();const models=$('#referenceLearn').checked?[learnPhrases(reference,range.track),...(extraScore?[learnPhrases(extraScore,+$('#referenceExtraPart').value)]:[])]:[],model=blendPhraseModels(models);const settings={...readSongStructure('reference'),referenceScore:reference,...range,mode:$('#referenceMode').value,influence:+$('#referenceInfluence').value,usage:$('#referenceUsage').value,scope:$('#referenceScope').value,lockPitch:$('#referencePitch').checked,lockRhythm:$('#referenceRhythm').checked,learned:model,learningInfluence:+$('#referenceLearning').value,mood:$('#referenceMood').value,genre:$('#referenceGenre').value,key:+$('#referenceKey').value,scale:$('#referenceScale').value,tempo:+$('#referenceTempo').value,seed:+$('#referenceSeed').value,complexity:+$('#referenceComplexity').value,adventure:+$('#referenceAdventure').value};const treatment=$('#referenceTreatment').value,engine=$('#referenceEngine').value,useNeural=engine!=='phrase',sourceReference=reference,sourceRange={...range};score=composeSong(useNeural?{...settings,referenceScore:undefined}:settings);if(useNeural){score=await neural.generate(score,{...settings,engine,referenceScore:settings.mode==='inspired'&&!settings.influence?undefined:sourceReference,temperature:+$('#referenceTemperature').value,onProgress:message=>{if($('#referenceReport'))$('#referenceReport').textContent=message;}});score=applySongMotif(score,sourceReference,settings);}if(treatment!=='none')score=applyShatteredTreatment(score,{mode:treatment,seed:settings.seed});if(revision!==serial)throw Object.assign(Error('Generation stopped.'),{name:'AbortError'});score.reference={range:sourceRange,mode:$('#referenceMode').value,songs:[{id:primary.id,name:primary.name,part:range.track},...(extraScore?[{id:$('#referenceExtra').value,part:+$('#referenceExtraPart').value}]:[])]};const candidate=compileMusic(score,{name:$('#referenceName').value.trim()||'New theme'}),stats=checkScore(score);$('#referenceReport').textContent=`${score.composition.neural?score.composition.neural.engine+' melody · ':''}${stats.notes} notes · ${score.composition.motif.placements.length} scheduled motif appearances · ${(candidate.sourceBytes/1024).toFixed(1)} KB${score.composition.treatment?' · Worn treatment':''}`;$('#referenceLearningReport').textContent=model?`Analysed ${model.notes} notes across ${model.bars} source bars in ${models.length} selected part${models.length===1?'':'s'}.`:'Full-song phrase analysis is off.';return candidate;}
 const modeControls=()=>{const exact=$('#referenceMode').value==='motif';for(const id of ['referencePitch','referenceRhythm'])$('#'+id).disabled=!exact;$('#referenceInfluence').disabled=exact;};
 $('#referenceSource').onchange=safe(()=>{api.stop();const t=sources.find(t=>t.id===$('#referenceSource').value);let next;try{next=t===initial?initialScore:musicScore(t.asset).score;}catch(e){$('#referenceSource').value=primary.id;throw e;}reference=next;primary=t;range.track=reference.tracks.findIndex(t=>t.notes.length);const first=reference.tracks[range.track].notes[0]?.tick||0;range.start=first;range.end=Math.min(reference.length,first+192);drawParts();drawExtra();$('#referenceName').value=primary.name+' new theme';$('#referenceOriginal').disabled=!primary.asset;});
 $('#referencePart').onchange=safe(()=>{range.track=+$('#referencePart').value;const first=reference.tracks[range.track].notes[0]?.tick||0;range.start=first;range.end=Math.min(reference.length,first+192);drawRange();});for(const id of ['referenceStartBar','referenceEndBar'])$('#'+id).onchange=safe(()=>{readRange();rangeView.refresh(range);});$('#referenceExtra').onchange=safe(loadExtra);$('#referenceExtraPart').onchange=()=>{};$('#referenceMode').onchange=modeControls;$('#referenceLearn').onchange=()=>{for(const id of ['referenceLearning','referenceExtra','referenceExtraPart'])$('#'+id).disabled=!$('#referenceLearn').checked;};
 $('#referenceMood').onchange=()=>{const p=MUSIC_MOODS[$('#referenceMood').value];$('#referenceScale').value=p.scale;$('#referenceTempo').value=p.tempo;describe();};$('#referenceGenre').onchange=describe;$('#referenceTreatment').onchange=()=>{cancel();describe();};
 for(const [id,out]of [['referenceInfluence','referenceInfluenceValue'],['referenceLearning','referenceLearningValue']])$('#'+id).oninput=()=>$('#'+out).textContent=$('#'+id).value;
 $('#referenceHearRiff').onclick=safe(()=>{readRange();const clip=arrangeSections({...reference,tracks:[{...reference.tracks[range.track],program:0}]},[{from:range.start,to:range.end}]);clip.loopStart=0;return api.play(compileMusic(clip));});$('#referencePreview').onclick=safe(async job=>{const asset=await build();if(job===serial)return api.play(asset);});$('#referenceOriginal').onclick=safe(()=>api.play(primary.asset));$('#referenceStop').onclick=()=>{cancel();$('#referenceReport').textContent='Stopped.';};$('#referenceNext').onclick=safe(async job=>{$('#referenceSeed').value=(+$('#referenceSeed').value+1)>>>0;const asset=await build();if(job===serial)return api.play(asset);});
 drawParts();drawExtra();describe();modeControls();$('#referenceTemperature').oninput=()=>{cancel();$('#referenceTemperatureValue').textContent=$('#referenceTemperature').value;};const setEngine=()=>{cancel();const value=$('#referenceEngine').value;$('#referenceTemperature').disabled=value==='phrase';$('#referenceEngineHint').textContent=value==='musigan'?'The contour stage runs locally.':value==='hybrid'?'Hybrid develops a connected, chord-aware Pokémon/GBA-style phrase while preserving the selected motif as the inspiration source.':value==='magenta'?'The melody stage develops phrases over the arrangement’s chords.':'The instant composer uses the selected motif and learned phrase rules.';};$('#referenceEngine').onchange=setEngine;setEngine();document.querySelector('#dialog')?.addEventListener('close',()=>{body?.removeEventListener('input',cancel);cancel();},{once:true});$('#referenceReport').textContent='Ready. Preview or arrange to generate a track.';
}
